def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Este capítulo es un taller de método: recoge las herramientas con las que se ha escrito el resto del libro y que el lector puede aplicar a cualquier texto histórico. Explica qué es una fuente, cómo se clasifican, cómo se critican y se contrastan, qué archivos conservan la documentación de la Monarquía, cómo se escribió la historia de España desde las crónicas y qué debates historiográficos siguen abiertos. El objetivo práctico es que el lector pueda comentar un documento, ordenar una cronología y distinguir una afirmación apoyada en fuentes de una opinión.',
        quotes=[Q('es_fuente', 'Una fuente documental es el origen de la información usada especialmente para una investigación'), Q('es_historiografia', 'Para investigar e interpretar las sociedades, los historiadores recurren a fuentes históricas')]))
    P.append(dict(text='Fuente y documento\nLa fuente es el origen de la información; el documento es su soporte. Un ejemplo de la propia enciclopedia: ante el folleto ¿Qué es el tercer estado? de Sieyès, la fuente es el abate que habla y el documento es el escrito divulgado por la imprenta. Una definición amplia, recogida por la fuente inglesa, entiende por fuente histórica toda clase de huella que los seres humanos han dejado de sus actividades pasadas: la palabra escrita y hablada, el paisaje, el objeto material, las bellas artes, la fotografía y el cine. Aun así, la misma fuente reconoce que el estudio de la historia se ha basado casi siempre en lo que el historiador puede leer en documentos o escuchar a informantes.',
        quotes=[Q('es_fuente', 'El documento es el soporte de la fuente.'), Q('es_fuente', 'la fuente es el abate Emmanuel Joseph Sieyès (es él quien habla); el documento es un escrito divulgado por la imprenta'), Q('en_source', 'every kind of evidence that human beings have left of their past activities'), Q('en_source', 'the study of history has nearly always been based squarely on what the historian can read in documents')]))
    P.append(dict(text='Fuentes primarias, secundarias y terciarias\nLa clasificación por orden de precedencia distingue tres niveles. La fuente primaria procede directamente de la época que se investiga: las leyes, los tratados y las memorias son testimonios de primera mano. La fuente secundaria es posterior al periodo estudiado y reelabora la información obtenida de las primarias mediante generalización, análisis, síntesis, interpretación o evaluación; son libros, artículos y mapas. La fuente terciaria es una selección y recopilación de fuentes primarias y secundarias, como una bibliografía, un catálogo o una lista de lecturas, y no añade interpretación propia. La fuente inglesa coincide en la idea de que una fuente primaria se hizo durante el periodo investigado y de que la secundaria da información sobre una primaria.',
        quotes=[Q('es_historiografia', 'Una fuente primaria procede directamente de la época que se está investigando'), Q('es_historiografia', 'Son los testimonios de primera mano, es decir, las leyes, los tratados, las memorias, etc.'), Q('es_fuente', 'Fuente terciaria: es una selección y recopilación de fuentes primarias y secundarias'), Q('en_source', 'Primary sources were made during the historical period that is being investigated.'), Q('en_source', 'A secondary source is one that gives information about a primary source.')]))
    P.append(dict(role='definition', text='Fuente primaria: material de primera mano, producido en la época que se investiga, que sirve para reconstruir los hechos; en historia son las leyes, los tratados, las memorias, las cartas, los registros y los objetos de esa época. Ejemplos de este libro: el testamento de Isabel la Católica, las capitulaciones de Santa Fe, la Brevísima relación de Las Casas y los decretos de Nueva Planta. Los libros y artículos de síntesis, incluida la enciclopedia que se cita en las notas, son fuentes secundarias.',
        quotes=[Q('es_fuente', 'Fuente primaria: es el material de primera mano relativo a un fenómeno que se desea investigar.'), Q('en_source', 'a first hand account of events by someone who lived through them')]))
    P.append(dict(text='Según la forma de expresión\nPor su forma de expresión, las fuentes pueden ser orales, arqueológicas, escritas, audiovisuales y gráficas. Entre las escritas, la fuente documental distingue la bibliográfica (los libros, que se recopilan en bibliotecas), la hemerográfica (periódicos y revistas), la epigráfica (inscripciones en espacios públicos y monumentos) y la archivística, que es la no publicada, la que produjo una persona o institución para su propio uso y que queda depositada en un archivo. La enciclopedia añade que las fuentes gráficas, es decir, la fotografía y las imágenes, se conservan en fototecas y museos. Una historia del siglo XVI se apoya sobre todo en la fuente archivística y en la escrita impresa, pero también en la fuente gráfica (retratos, mapas, grabados) y en la arqueológica.',
        quotes=[Q('es_fuente', 'Fuente archivística; la no publicada, sino restringida para su propio uso por quien la produjo'), Q('es_fuente', 'Fuente epigráfica; la que se manifiesta en espacios públicos'), Q('es_fuente', 'Fuente hemerográfica; la de publicación periódica: sus documentos son los periódicos y revistas.'), Q('en_source', 'the shape of the landscape and the material artefact')]))
    P.append(dict(text='Los archivos de la Monarquía\nLa documentación de la Monarquía creció tan deprisa que no podía seguir a una corte itinerante, y Carlos V ordenó crear el Archivo General de Simancas ({{fig:simancas}}). En 1567 Felipe II encargó a Jerónimo Zurita reunir los documentos de Estado de Aragón e Italia y juntarlos con los de Castilla en el castillo de Simancas, y así se creó uno de los mayores archivos nacionales de su tiempo. La documentación de las Indias tiene otro lugar: el Archivo General de Indias, en Sevilla, guarda los papeles del Consejo de Indias y ocupa el edificio renacentista de la Casa de Contratación, construido sobre planos de Juan de Herrera y declarado Patrimonio de la Humanidad por la Unesco en 1987 ({{fig:agi}}). Dos archivos, dos lógicas: el de Simancas conserva el gobierno de los reinos peninsulares y de Europa; el de Sevilla, el gobierno de las Indias.',
        quotes=[Q('es_antiguo_regimen', 'Carlos V ordenó crear el Archivo General de Simancas'), Q('es_felipe2', 'En 1567 Felipe II encargó a Jerónimo Zurita y Castro reunir los documentos de Estado de Aragón e Italia'), Q('en_consejo_indias', 'the General Archive of the Indies (Spanish: Archivo General de Indias) one of the major centers of documentation for Spanish, Spanish American, and European history, are housed in Seville'), Q('es_casa_contratacion', 'El edificio renacentista construido sobre planos de Juan de Herrera, alberga hoy en día el Archivo General de Indias y fue declarado Patrimonio de la Humanidad por la Unesco en 1987.')]))
    P.append(dict(text='Cómo se trata una fuente\nEl tratamiento científico de una fuente sigue cuatro pasos. Primero, la reunión de un corpus documental suficiente de todas las fuentes de información que interesan. Segundo, la crítica de fuentes: el juicio del investigador sobre su sinceridad y su correspondencia con la realidad. Tercero, el contraste entre fuentes, para ver si coinciden o discrepan y en qué grado. Cuarto, el respeto a la fuente, que obliga a no falsearla ni tergiversarla para que diga lo que al investigador le interesa. La enciclopedia que sintetiza la historiografía resume el mismo proceso con tres palabras: reunión, crítica y contraste. Este libro ha seguido el proceso de forma deliberada: cada párrafo se apoya en extractos de dos fuentes distintas y se revisa su correspondencia.',
        quotes=[Q('es_fuente', 'El primer paso de cualquier investigación es la reunión de un corpus documental suficiente'), Q('es_fuente', 'del juicio que el investigador (periodista o historiador, por ejemplo) deben de hacer sobre su sinceridad y correspondencia con la realidad'), Q('es_fuente', 'las fuentes deben contrastarse entre ellas, viendo si coinciden o discrepan, y en qué grado'), Q('es_fuente', 'no falsearlas ni tergiversarlas para hacerlas decir lo que al investigador interesa que digan'), Q('es_historiografia', 'su tratamiento (reunión, crítica, contraste)')]))
    P.append(dict(text='Un caso de crítica: la Brevísima relación\nLa Brevísima relación de la destrucción de las Indias es una fuente primaria de la primera colonización y un caso ejemplar de crítica. La enciclopedia señala que un historiador americanista tiene que usarla, porque Las Casas la escribió con un afán histórico indudable, pero también con el propósito de defender un interés y su propio punto de vista. Esa doble naturaleza es el centro de la crítica: es un testimonio y a la vez una alegación. Quien la lea sin crítica creerá que describe sin más lo que pasó; quien la descarte por parcial perderá un testimonio valioso. El método consiste en preguntar quién escribe, cuándo, para quién, con qué fin y con qué pruebas, y comparar después con otras fuentes.',
        quotes=[Q('es_historiografia', 'con un afán histórico indudable, además de con un propósito de la defensa de un interés o su propio punto de vista'), Q('en_casas', 'One of the stated purposes for writing the account was Las Casas'), Q('es_casas', 'dirigida al príncipe Felipe, futuro rey Felipe II')]))
    P.append(dict(text='Cuándo se escribió y cuándo se publicó\nLa datación es el primer paso de la crítica, y la Brevísima la complica. El texto dice de sí mismo que fue escrito en 1542: según Las Casas, han pasado cuarenta y nueve años desde que las Indias fueron pobladas por los españoles, «en este de 1542 en que escribo». La obra se publicó en Sevilla en 1552, diez años después, ({{fig:brevisima}}). Entre la escritura y la imprenta hay un hueco de una década, y esa diferencia importa: lo que se lee en 1552 refleja lo que Las Casas sabía y quería denunciar en 1542, no la situación del momento de la publicación.',
        quotes=[Q('ws_brevisima', 'hace cuarenta y nueve años en este de 1542 en que escribo'), Q('en_casas', 'written in 1542 (published in Seville in 1552)'), Q('es_casas', 'Brevísima relación de la destrucción de las Indias (1552)')]))
    P.append(dict(text='Leer el texto: retórica y cifras\nUn comentario atento a la retórica de la Brevísima distingue lo que describe de lo que pretende. Los indios son retratados como gentes sencillas, sin iniquidad ni doblez, pacientes y pacíficas, y los españoles como lobos, tigres y leones hambrientos que persiguen a «mansísimas ovejas». La oposición moral es absoluta y la intención es persuadir. Las cifras tienen el mismo carácter: Las Casas sostiene que en La Española quedan doscientas personas naturales de allí tras haber llegado a ser tres millones. Son cifras redondas que no proceden de un recuento, y por eso hay que tratarlas como una estimación con propósito retórico y no como un dato estadístico; esa es la diferencia entre el testimonio de un contemporáneo y una serie demográfica.',
        quotes=[Q('ws_brevisima', 'Las gentes de todos aquellos vastísimos países son sencillas, sin iniquidad, ni doblez'), Q('ws_brevisima', 'Los españoles trataron a estas mansísimas ovejas, y olvidándose de ser hombres, y ejerciendo la crueldad de lobos, de tigres, y de leones hambrientos'), Q('ws_brevisima', 'Así hay ahora en la Isla Española solo doscientas personas naturales de allí, habiendo habido en el principio hasta tres millones.'), Q('es_casas', 'sobre el nulo valor documental de la Brevísima relación de la destrucción de las Indias, su partidismo y su demencial exageración')]))
    P.append(dict(text='Los usos posteriores de una fuente\nUna fuente también tiene una historia de lectores. La obra se tradujo al neerlandés en 1578, durante las guerras de religión, y se editó en francés, inglés y alemán en países enfrentados con la Monarquía; los grabados de Theodor de Bry ilustraron después sus escenas. Según la fuente inglesa, el libro se convirtió en un elemento de la creación y propagación de la Leyenda Negra, la tradición que describe al Imperio español como excepcionalmente violento. A fines del siglo XIX y comienzos del XX, historiadores nacionalistas españoles construyeron una Leyenda Blanca de signo contrario, y algunos llamaron a Las Casas paranoico y exagerado. La conclusión metodológica es que el uso que se hizo de una fuente no prueba nada sobre su verdad, pero explica por qué se discute.',
        quotes=[Q('en_casas', 'The first edition in translation was published in Dutch in 1578'), Q('en_casas', 'The images described by Las Casas were later depicted by Theodore de Bry'), Q('en_casas', 'The book became an important element in the creation and propagation of the so-called Black Legend'), Q('en_casas', 'Opposition to Las Casas reached its climax in historiography with Spanish right-wing, nationalist historians'), Q('es_casas', 'Ramón Menéndez Pidal en su obra El Padre Las Casas: su doble personalidad lo acusa de haber promovido la leyenda negra')]))
    P.append(dict(text='Historiadores que discrepan\nLos historiadores valoran la Brevísima de maneras opuestas, y esas valoraciones son la propia historiografía. Según la fuente en español, Menéndez Pidal acusó a Las Casas de haber promovido la leyenda negra, y Julián Marías habló del nulo valor documental de la obra por su partidismo y su exageración. Otros, como William Maltby y Guillermo Macías, consideran que sus inexactitudes fueron más bien accidentales y se debieron a su extrema devoción por defender los derechos de los indios. La fuente inglesa resume que su legado ha sido muy controvertido. Entre una postura y otra, el lector puede aceptar el testimonio de Las Casas sobre lo que vio, cuestionar sus generalizaciones y no confundirlas: ese es el trabajo del contraste.',
        quotes=[Q('es_casas', 'Ramón Menéndez Pidal en su obra El Padre Las Casas: su doble personalidad lo acusa de haber promovido la leyenda negra'), Q('es_casas', 'sostienen un juicio más indulgente al considerar que sus inexactitudes habrían sido algo mayormente accidental'), Q('en_casas', "Las Casas's legacy has been highly controversial.")]))
    P.append(dict(text='Cuando las fuentes discrepan: la fecha de Annales\nEl contraste de fuentes no solo sirve para los grandes juicios: también descubre discrepancias pequeñas. La revista Annales d\'histoire économique et sociale, de Lucien Febvre y Marc Bloch, se funda, según la fuente en español, en 1928; la fuente inglesa dice que fue fundada en 1929 en Estrasburgo. Las dos fuentes dan datos distintos y el historiador no debe elegir al azar ni copiar la primera que lea. Debe buscar una fuente primaria o una obra de referencia (por ejemplo, el primer número de la revista), registrar la discrepancia y citar lo que corresponda. En una pieza de estudio, una nota que diga «1928 o 1929 según las fuentes consultadas» es mejor que una fecha segura pero no comprobada.',
        quotes=[Q('es_historiografia', 'fundada por Lucien Febvre y Marc Bloch en 1928'), Q('en_historiography', 'was founded in 1929 in Strasbourg by Marc Bloch and Lucien Febvre')]))
    P.append(dict(role='consejo', text='Para comentar un documento, siga siempre el mismo guion: 1) identifique el tipo de fuente (primaria o secundaria, jurídica, narrativa, privada, gráfica); 2) sitúela en su fecha y contexto; 3) enuncie la idea principal y las secundarias; 4) analice el vocabulario y la retórica; 5) valore su alcance y sus límites, y qué no puede responder; 6) contraste con otra fuente. El orden evita la paráfrasis, que es el error más habitual en los comentarios de texto.',
        quotes=[Q('es_fuente', 'del juicio que el investigador (periodista o historiador, por ejemplo) deben de hacer sobre su sinceridad y correspondencia con la realidad'), Q('es_historiografia', 'su tratamiento (reunión, crítica, contraste)')]))
    P.append(dict(text='Historia, historiografía e historiología\nLa enciclopedia propone una distinción sintética entre tres términos que suelen confundirse. Historia son los hechos del pasado; historiografía es la ciencia que estudia y escribe la historia, y la que analiza los métodos, las fuentes, los productos y los autores; historiología, término propuesto por Ortega y Gasset, es la epistemología de la historia, el estudio de la estructura, las leyes y las condiciones de la realidad histórica. La historiografía se emplea también para el conjunto de escritos sobre un tema, como cuando se dice que es muy escasa la historiografía sobre la vida cotidiana en el Japón de la era Meiji. La fuente inglesa añade que todo historiador usa una o varias tradiciones historiográficas, por ejemplo la marxista o la de los Annales.',
        quotes=[Q('es_historiografia', 'Historia: los hechos del pasado.'), Q('es_historiografia', 'Historiografía: la ciencia que estudia y escribe la historia.'), Q('es_historiografia', 'Historiología: la epistemología de la historia.'), Q('en_historiography', 'Every historian uses one (or more) historiographical traditions')]))
    P.append(dict(text='Las crónicas medievales y modernas\nLa historiografía española es, según la enciclopedia, uno de los ejemplos más completos de un esfuerzo secular por mantener la continuidad de la memoria escrita. Las crónicas medievales justificaban la Reconquista para afianzar el poder de los reyes; las de Pedro López de Ayala, en el siglo XIV, son más sobrias y pegadas a los hechos que las europeas contemporáneas, aunque su fin primordial fuera la autojustificación de su autor. En el siglo XVI el Padre Mariana continuó esa función con la Historia de España (De rebus Hispaniae, 1592), célebre también por su defensa del tiranicidio, y Jerónimo Zurita escribió los Anales de la Corona de Aragón ({{fig:zurita}}). Para el historiador del siglo XXI, estas obras son a la vez una fuente secundaria sobre el pasado remoto y una fuente primaria sobre las ideas políticas de quien las escribió.',
        quotes=[Q('es_historiografia', 'la historiografía española es quizá el ejemplo más completo de un secular esfuerzo por mantener la continuidad de la memoria escrita del pasado'), Q('es_historiografia', 'De Rebus Hispaniae libri XX, 1592'), Q('es_historiografia', 'Jerónimo Zurita (Anales de la Corona de Aragón)'), Q('es_felipe3', 'El jesuita español Juan de Mariana denunció en su obra De monetae mutatione (1609)')]))
    P.append(dict(text='Cronistas de Indias y reflexión historiográfica\nEl cargo de Cronista de Indias se inició oficialmente con la documentación reunida por Pedro Mártir de Anglería, que pasó en 1526 a fray Antonio de Guevara. Hacia fines del siglo XVII la acumulación de un corpus cronístico tan grande hizo surgir la reflexión sobre la historiografía misma: el primer intento fue la Noticia y juicio de los más principales historiadores de España, del marqués de Mondéjar, publicada tras su muerte en 1708. Es un buen ejemplo de cómo un género se vuelve autorreflexivo cuando acumula obras que hay que ordenar y juzgar, y por eso se cita aquí como el inicio de la crítica de fuentes en España.',
        quotes=[Q('es_historiografia', 'Oficialmente el cargo de Cronista de Indias se inicia con la documentación reunida por Pedro Mártir de Anglería que se pasa en 1526'), Q('es_historiografia', 'la reflexión sobre la historiografía misma surge en España como necesidad derivada de la acumulación de tan ingente corpus cronístico'), Q('es_historiografia', 'publicado tras su muerte en 1708'), Q('es_casa_contratacion', 'Archivo General de Indias')]))
    P.append(dict(text='Falsificaciones y fraudes\nLa crítica de fuentes sirve también para detectar fraudes. La enciclopedia recuerda que la historiografía barroca incluyó manipulaciones fantasiosas, como los plomos del Sacromonte y los falsos cronicones, y que sobrepasar la frontera de la historia excéntrica es entrar en el fraude histórico, del que son ejemplos antiguos la Donación de Constantino, que justificó el poder temporal de los papas, y los Protocolos de los Sabios de Sión. En el caso de los plomos de Granada, la fuente sobre la expulsión de los moriscos los describe como un intento desesperado de un grupo de moriscos de legitimar su estancia en España. La lección es que una falsificación también es una fuente: miente sobre el pasado que dice contar, pero informa sobre quién la fabricó y con qué fin.',
        quotes=[Q('es_historiografia', 'La historiografía barroca incluye fantasiosas manipulaciones históricas, como los plomos del Sacromonte'), Q('es_historiografia', 'Sobrepasar la frontera de la historia excéntrica es entrar de lleno en el fraude histórico'), Q('es_historiografia', 'desde la Donación de Constantino (que justificó el poder temporal de los papas)'), Q('es_moriscos', 'Aparecen en Granada los falsos plomos del Sacromonte y los manuscritos de la Torre Turpiana')]))
    P.append(dict(text='Tiempos de la historia\nEl historiador elige cómo ordena el tiempo. La periodización clásica en Prehistoria, Edad Antigua, Edad Media, Edad Moderna y Edad Contemporánea es discutible por la necesidad de periodos de transición y de solapamientos y porque no representa periodos coincidentes para todos los países; y también se usan las historias por siglos y por reinados. El tratamiento diacrónico estudia la evolución de un hecho a lo largo del tiempo; el sincrónico compara cómo es el hecho en el mismo momento pero en planos distintos. Según Fernand Braudel, las concepciones del tiempo histórico van desde la larga duración al acontecimiento puntual, pasando por la coyuntura. La fuente inglesa precisa que Braudel desarrolló la idea de distintos modos del tiempo histórico en su estudio del Mediterráneo en la época de Felipe II.',
        quotes=[Q('es_historiografia', 'La periodización clásica'), Q('es_historiografia', 'El tratamiento diacrónico estudia la evolución temporal de un hecho'), Q('es_historiografia', 'según Fernand Braudel van desde la larga duración al acontecimiento puntual, pasando por la coyuntura'), Q('en_historiography', 'different modes of historical time')]))
    P.append(dict(text='La escuela de Annales\nLa escuela de Annales transformó la historia al ampliar su objeto más allá del acontecimiento y situarlo en la larga duración, y al pedir la confluencia con otras ciencias, sobre todo la sociología. Según la fuente inglesa, cambió el foco de la investigación francesa del siglo XX al subrayar la historia social a largo plazo, y no los temas políticos o diplomáticos, con atención a la cuantificación y a la geografía. En el testimonio histórico cambió el papel: ya no es el objeto, sino un útil para construir la historia, que puede obtenerse de cualquier dominio del conocimiento. Este libro usa la cronología narrativa, pero toma de Annales la idea de que una sociedad se explica por sus estructuras (población, economía, instituciones) y no solo por los acontecimientos.',
        quotes=[Q('es_historiografia', 'ampliando su objeto más allá del acontecimiento e inscribiéndola en la larga duración'), Q('en_historiography', 'stressing long-term social history, rather than political or diplomatic themes'), Q('es_historiografia', 'El papel del testimonio histórico cambia')]))
    P.append(dict(text='Un debate abierto: la Guerra de los Segadores\nLa historiografía no es una lista de nombres sino un debate. La Guerra de los Segadores muestra tres interpretaciones. La historiografía catalana del siglo XIX y principios del XX la presentó como un alzamiento de Cataluña contra la política desnacionalizadora de Olivares. Una corriente posterior, auspiciada por Jaume Vicens Vives y basada en los estudios de John H. Elliott, subrayó su carácter social más que nacional: la lucha de los pobres contra los ricos y la reacción de unas oligarquías que veían amenazados sus privilegios. Xavier Torres propone una tercera lectura, entre ambas: hubo un patriotismo catalán genuino, pero un patriotismo sin nación, que no debe confundirse con el nacionalismo. Los tres historiadores leen las mismas fuentes y llegan a conclusiones distintas porque hacen preguntas distintas.',
        quotes=[Q('es_segadores', 'presentó la Guerra dels Segadors como un «alzamiento de Cataluña»'), Q('es_segadores', 'hizo hincapié en el carácter «social» de la revuelta más que en su carácter «nacional»'), Q('es_segadores', 'un patriotismo sin nación'), Q('en_reapers', 'The Revolt of the Catalans: a Study in the Decline of Spain (1598–1640). Cambridge, 1963.')]))
    P.append(dict(text='Hispanistas y renovación metodológica\nLa disponibilidad de documentación en los archivos españoles atrajo a historiadores formados en universidades europeas y norteamericanas, en una especie de fuga de cerebros al revés que renovó la metodología. La enciclopedia cita, entre los franceses, a Bataillon, Vilar, Bennassar y Joseph Pérez, y entre los anglosajones a Brenan, Hugh Thomas, John Elliott, John Lynch, Henry Kamen e Ian Gibson. Entretanto, las universidades españolas se vaciaron por la guerra civil y el exilio, y a mediados del siglo XX se debe a Jaume Vicens Vives la creación del Índice Histórico Español en 1952. Muchas de las obras que se citan en este libro (la biografía de Olivares por Elliott, por ejemplo) son producto de esa renovación.',
        quotes=[Q('es_historiografia', 'una especie de fuga de cerebros al revés que renovó la metodología y las perspectivas de los historiadores españoles'), Q('es_historiografia', 'John Elliott (que con El Conde-Duque de Olivares ha dado muestra de cómo puede una biografía reflejar una época)'), Q('es_historiografia', 'creación del Índice Histórico Español en 1952'), Q('es_segadores', 'basada en los estudios de John H. Elliott')]))
    P.append(dict(text='Citar y no copiar\nLa enciclopedia plantea el respeto a las fuentes como deber del investigador: la investigación original no debe ocultar las fuentes en las que se basa y, si su aportación original es insuficiente o irrelevante, no hay originalidad sino plagio. Pide también un uso cuidadoso de la intertextualidad, que consiste en no entrecomillar a lo largo del texto pero reconocer en el propio texto, a pie de página o al final de la obra que lo dicho tiene una fuente. La Historiografía añade que el respeto se concreta en la cita fiel. En este libro el criterio es el mismo: cada párrafo remite a las fuentes consultadas y las citas literales de los ejercicios proceden del texto que se comenta, no de la memoria.',
        quotes=[Q('es_fuente', 'La investigación original no debe ocultar las fuentes en las que se basa.'), Q('es_fuente', 'Si la aportación original es insuficiente o irrelevante, no hay originalidad sino plagio.'), Q('es_historiografia', 'el mantener el respeto debido a las fuentes, fundamentalmente con su cita fiel')]))
    P.append(dict(text='Una cronología comparada\nLas fechas de este capítulo muestran cómo se escribió la historia de la Monarquía: en 1542 Las Casas escribe la Brevísima, que se publica en Sevilla en 1552; en 1567 Felipe II encarga a Zurita reunir los papeles de Aragón e Italia en Simancas; en 1592 se publica la Historia de España de Mariana; en 1708 aparece póstumo el primer juicio crítico de los historiadores españoles; en 1928 o 1929, según la fuente, nace la revista Annales; y en 1952 se crea el Índice Histórico Español. La línea de tiempo que acompaña estas páginas ({{fig:historiografia-cronologia}}) resume esas fechas y recuerda que la historia tiene también su propia historia.',
        quotes=[Q('en_casas', 'written in 1542 (published in Seville in 1552)'), Q('es_felipe2', 'En 1567 Felipe II encargó a Jerónimo Zurita y Castro reunir los documentos de Estado de Aragón e Italia'), Q('es_historiografia', 'De Rebus Hispaniae libri XX, 1592'), Q('es_historiografia', 'publicado tras su muerte en 1708'), Q('es_historiografia', 'creación del Índice Histórico Español en 1952')]))
    P.append(dict(role='self_check', text='¿Qué diferencia hay entre fuente y documento? ¿Cuándo se escribió y cuándo se publicó la Brevísima, y por qué importa? ¿Qué cuatro pasos tiene el tratamiento de una fuente? ¿Qué diferencia hay entre una fuente terciaria y una secundaria? ¿Por qué dos fuentes pueden dar fechas distintas para la fundación de Annales? ¿Qué tres lecturas hay de la Guerra de los Segadores?',
        quotes=[Q('es_fuente', 'El documento es el soporte de la fuente.'), Q('en_source', 'A tertiary source is an index or textual consolidation of already published primary and secondary sources')]))
    return P


