                  dict(label='Tipo de fuente y contexto', points=[
                    dict(text='Es una fuente primaria escrita, de una obra que su autor dice haber escrito en 1542 y que se publicó en Sevilla en 1552; la enciclopedia señala que su autor la dirigió al príncipe Felipe, futuro Felipe II.', quotes=[Q('ws_brevisima', 'hace cuarenta y nueve años en este de 1542 en que escribo'), Q('en_casas', 'written in 1542 (published in Seville in 1552)'), Q('es_casas', 'dirigida al príncipe Felipe, futuro rey Felipe II')])]),
